// Dos verificadores para el mismo token ES256. Las claves se generan acá; los datos son inventados.
const enc = new TextEncoder(), dec = new TextDecoder();
const b64u = (b) => btoa(String.fromCharCode(...new Uint8Array(b))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const deb64u = (s) => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/')), (c) => c.charCodeAt(0));
const json = (o) => b64u(enc.encode(JSON.stringify(o)));

const par = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
const pub = new Uint8Array(await crypto.subtle.exportKey('spki', par.publicKey)); // la clave pública la conoce cualquiera
const ISS = 'https://auth.practica.local', AUD = 'api-despachos';
const ahora = Math.floor(Date.now() / 1000);

async function emitir(carga) {
  const c = json({ alg: 'ES256', typ: 'JWT' }), p = json(carga);
  const f = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, par.privateKey, enc.encode(c + '.' + p));
  return `${c}.${p}.${b64u(f)}`;
}
async function firmaOk(alg, t) {
  const [c, p, f] = t.split('.');
  const dato = enc.encode(c + '.' + p);
  if (alg === 'ES256') {
    const k = await crypto.subtle.importKey('spki', pub, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
    return crypto.subtle.verify({ name: 'ECDSA', hash: 'SHA-256' }, k, deb64u(f), dato);
  }
  if (alg === 'HS256') { // «la clave configurada» es la pública y el verificador la usa como secreto de HMAC
    const k = await crypto.subtle.importKey('raw', pub, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify']);
    return crypto.subtle.verify('HMAC', k, deb64u(f), dato);
  }
  return false;
}
async function ingenuo(t) { // confía en la cabecera y no mira los claims
  const alg = JSON.parse(dec.decode(deb64u(t.split('.')[0]))).alg;
  if (alg === 'none') return 'ACEPTADO (sin firma)';
  return (await firmaOk(alg, t)) ? 'ACEPTADO' : 'rechazado: firma';
}
async function completo(t) { // algoritmo fijado por nosotros y todos los claims revisados
  const [c, p] = t.split('.');
  const cab = JSON.parse(dec.decode(deb64u(c))), carga = JSON.parse(dec.decode(deb64u(p)));
  if (cab.alg !== 'ES256') return `rechazado: alg ${cab.alg}`;
  if (!(await firmaOk('ES256', t))) return 'rechazado: firma';
  if (!(carga.exp > ahora)) return 'rechazado: vencido';
  if (carga.iss !== ISS) return 'rechazado: iss';
  if (carga.aud !== AUD) return 'rechazado: aud';
  return 'ACEPTADO';
}

const bueno = await emitir({ iss: ISS, sub: 'marta', aud: AUD, exp: ahora + 900, rol: 'miembro' });
const [c0, p0, f0] = bueno.split('.');
const admin = { iss: ISS, sub: 'marta', aud: AUD, exp: ahora + 900, rol: 'admin' };
const casos = {
  'token legítimo': bueno,
  'rol editado a admin': `${c0}.${json(admin)}.${f0}`,
  'alg none, sin firma': `${json({ alg: 'none', typ: 'JWT' })}.${json(admin)}.`,
  'HS256 firmado con la clave pública': await (async () => {
    const c = json({ alg: 'HS256', typ: 'JWT' }), p = json(admin);
    const k = await crypto.subtle.importKey('raw', pub, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    return `${c}.${p}.${b64u(await crypto.subtle.sign('HMAC', k, enc.encode(c + '.' + p)))}`;
  })(),
  'legítimo pero vencido': await emitir({ iss: ISS, sub: 'marta', aud: AUD, exp: ahora - 60, rol: 'miembro' }),
  'legítimo pero de otro servicio': await emitir({ iss: ISS, sub: 'marta', aud: 'api-facturas', exp: ahora + 900, rol: 'miembro' }),
};
for (const [nombre, t] of Object.entries(casos)) {
  console.log(nombre.padEnd(36), '| ingenuo:', (await ingenuo(t)).padEnd(24), '| completo:', await completo(t));
}
